from ortools.sat.python import cp_model

n = 15
model = cp_model.CpModel()

# edge variables
edge = {}
for u, v in combinations(range(n), 2):
    edge[(u,v)] = model.NewBoolVar(f"e_{u}_{v}")

# fixed edges
fixed = [(2,12),(3,10),(6,9),(3,13),(3,12),(0,13)]
for u,v in fixed:
    if u > v:
        u,v = v,u
    model.Add(edge[(u,v)] == 1)

# degree constraints
for vtx in range(n):
    incident = []
    for u in range(n):
        if u == vtx:
            continue
        a,b = (min(u,vtx), max(u,vtx))
        incident.append(edge[(a,b)])
    model.Add(sum(incident) >= 2)
    model.Add(sum(incident) <= 5)

# no triangles
for i,j,k in combinations(range(n), 3):
    e1 = edge[(min(i,j), max(i,j))]
    e2 = edge[(min(j,k), max(j,k))]
    e3 = edge[(min(i,k), max(i,k))]
    model.Add(e1 + e2 + e3 <= 2)

solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 30.0
solver.parameters.num_search_workers = 8
print("Solving with CP-SAT...")
status = solver.Solve(model)
print("Status:", status, cp_model.OPTIMAL, cp_model.FEASIBLE, cp_model.INFEASIBLE)
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    edges = []
    for u,v in combinations(range(n),2):
        if solver.Value(edge[(u,v)]) == 1:
            edges.append((u,v))
    print("Edges:", len(edges))
    deg = [0]*n
    for u,v in edges:
        deg[u]+=1
        deg[v]+=1
    print("Degrees:", deg)
    # verify no triangles
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    tri = False
    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[j]:
                    if k > j and k in adj[i]:
                        tri = True
                        print("Triangle:", i,j,k)
                        break
                if tri:
                    break
        if tri:
            break
    print("Has triangle:", tri)
    print(sorted(edges))
else:
    print("No solution found")

