# verify girth >= 4 by checking shortest cycle length
from collections import deque

def shortest_cycle(adj, n):
    best = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a back edge
                    cycle_len = dist[u] + dist[v] + 1
                    best = min(best, cycle_len)
    return best

girth = shortest_cycle(adj, n)
print("Girth:", girth)

# Let's also just BFS from each node to find shortest cycle more carefully
def bfs_shortest_cycle_from(start, adj, n):
    dist = {start: 0}
    parent = {start: None}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                parent[v] = u
                q.append(v)
            elif parent[u] != v:
                # cycle found
                return dist[u] + dist[v] + 1
    return float('inf')

best = float('inf')
for start in range(n):
    best = min(best, bfs_shortest_cycle_from(start, adj, n))
print("Girth (BFS):", best)
